     9	
    10	    public final void process(EmailMessage message) {
    11	        if (shouldProcess(message)) {
    12	            doProcess(message);
    13	        }
    14	
    15	        if (!message.isBlocked() && next != null) {
    16	            next.process(message);
    17	        }
    18	    }
