    10	    public static boolean isValid(String email) {
    11	        if (email == null || email.isEmpty()) {
    12	            return false;
    13	        }
    14	
    15	        int atCount = 0;
    16	        for (char c : email.toCharArray()) {
    17	            if (c == '@') atCount++;
    18	        }
    19	        if (atCount != 1) {
    20	            return false;
    21	        }
    22	
    23	        String[] parts = email.split("@");
    24	        if (parts.length != 2) {
    25	            return false;
    26	        }
    27	
    28	        String before = parts[0];
    29	        String after = parts[1];
    30	
    31	        if (before.isEmpty()) {
    32	            return false;
    33	        }
    34	
    35	        if (after.indexOf('.') <= 0 || after.indexOf('.') >= after.length() - 1) {
    36	            return false;
    37	        }
    38	
    39	        return true;
    40	    }
    41	}
