    23	
    24	    public Reservation createReservation(
    25	        int roomNumber,
    26	        String guestName,
    27	        String guestEmail,
    28	        String guestCpf,
    29	        LocalDate checkIn,
    30	        LocalDate checkOut,
    31	        int guests,
    32	        RatePlan ratePlan
    33	    ) {
    34	        // Validate room
    35	        Room room = roomRepo.findByNumber(roomNumber)
    36	            .orElseThrow(() -> new IllegalArgumentException("Room not found"));
    37	
    38	        // Validate guests
    39	        if (guests < 1 || guests > room.capacity) {
    40	            throw new IllegalArgumentException("Invalid number of guests");
    41	        }
    42	
    43	        // Validate dates
    44	        if (!checkIn.isBefore(checkOut)) {
    45	            throw new IllegalArgumentException("Check-in must be before check-out");
    46	        }
    47	
    48	        // Check availability
    49	        checkRoomAvailability(roomNumber, checkIn, checkOut);
    50	
    51	        // Calculate tariff
    52	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    53	        var tarifPlan = TarifPlanFactory.create(ratePlan);
    54	        BigDecimal subtotal = tarifPlan.calculateSubtotal(room.nightlyRate, nights, checkIn);
    55	        BigDecimal discount = tarifPlan.calculateDiscount(subtotal);
    56	        BigDecimal total = Money.subtract(subtotal, discount);
    57	
    58	        Reservation reservation = new Reservation(
    59	            0,
    60	            roomNumber,
    61	            guestName,
    62	            guestEmail,
    63	            guestCpf,
    64	            checkIn,
    65	            checkOut,
    66	            guests,
    67	            ratePlan,
    68	            nights,
    69	            subtotal,
    70	            discount,
    71	            total
    72	        );
    73	
    74	        return reservationRepo.create(reservation);
    75	    }
