    14	
    15	public class ReservationService {
    16	    private final ReservationRepository reservationRepo;
    17	    private final RoomRepository roomRepo;
    18	
    19	    public ReservationService(ReservationRepository reservationRepo, RoomRepository roomRepo) {
    20	        this.reservationRepo = reservationRepo;
    21	        this.roomRepo = roomRepo;
    22	    }
    23	
    24	    public Reservation createReservation(
    25	        int roomNumber,
    26	        String guestName,
    27	        String guestEmail,
    28	        String guestCpf,
    29	        LocalDate checkIn,
    30	        LocalDate checkOut,
    31	        int guests,
    32	        RatePlan ratePlan
    33	    ) {
    34	        // Validate room
    35	        Room room = roomRepo.findByNumber(roomNumber)
    36	            .orElseThrow(() -> new IllegalArgumentException("Room not found"));
    37	
    38	        // Validate guests
    39	        if (guests < 1 || guests > room.capacity) {
    40	            throw new IllegalArgumentException("Invalid number of guests");
    41	        }
    42	
    43	        // Validate dates
    44	        if (!checkIn.isBefore(checkOut)) {
    45	            throw new IllegalArgumentException("Check-in must be before check-out");
    46	        }
    47	
    48	        // Check availability
    49	        checkRoomAvailability(roomNumber, checkIn, checkOut);
    50	
    51	        // Calculate tariff
    52	        int nights = (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    53	        var tarifPlan = TarifPlanFactory.create(ratePlan);
    54	        BigDecimal subtotal = tarifPlan.calculateSubtotal(room.nightlyRate, nights, checkIn);
    55	        BigDecimal discount = tarifPlan.calculateDiscount(subtotal);
    56	        BigDecimal total = Money.subtract(subtotal, discount);
    57	
    58	        Reservation reservation = new Reservation(
    59	            0,
    60	            roomNumber,
    61	            guestName,
    62	            guestEmail,
    63	            guestCpf,
    64	            checkIn,
    65	            checkOut,
    66	            guests,
    67	            ratePlan,
    68	            nights,
    69	            subtotal,
    70	            discount,
    71	            total
    72	        );
    73	
    74	        return reservationRepo.create(reservation);
    75	    }
    76	
    77	    public Reservation confirmReservation(long reservationId, BigDecimal amountPaid) {
    78	        Reservation reservation = reservationRepo.findById(reservationId)
    79	            .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
    80	
    81	        if (reservation.status != ReservationStatus.PENDING) {
    82	            throw new IllegalArgumentException("Cannot confirm non-pending reservation");
    83	        }
    84	
    85	        reservation.status = ReservationStatus.CONFIRMED;
    86	        reservation.amountPaid = amountPaid;
    87	
    88	        return reservationRepo.save(reservation);
    89	    }
    90	
    91	    public Reservation checkIn(long reservationId) {
    92	        Reservation reservation = reservationRepo.findById(reservationId)
    93	            .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
    94	
    95	        if (reservation.status != ReservationStatus.CONFIRMED) {
    96	            throw new IllegalArgumentException("Can only check in confirmed reservations");
    97	        }
    98	
    99	        reservation.status = ReservationStatus.CHECKED_IN;
   100	        return reservationRepo.save(reservation);
   101	    }
   102	
   103	    public Reservation checkOut(long reservationId) {
   104	        Reservation reservation = reservationRepo.findById(reservationId)
   105	            .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
   106	
   107	        if (reservation.status != ReservationStatus.CHECKED_IN) {
   108	            throw new IllegalArgumentException("Can only check out checked-in reservations");
   109	        }
   110	
   111	        reservation.status = ReservationStatus.CHECKED_OUT;
   112	        return reservationRepo.save(reservation);
   113	    }
   114	
   115	    public Reservation cancelReservation(long reservationId) {
   116	        Reservation reservation = reservationRepo.findById(reservationId)
   117	            .orElseThrow(() -> new IllegalArgumentException("Reservation not found"));
   118	
   119	        if (reservation.status != ReservationStatus.PENDING && reservation.status != ReservationStatus.CONFIRMED) {
   120	            throw new IllegalArgumentException("Can only cancel pending or confirmed reservations");
   121	        }
   122	
   123	        var tarifPlan = TarifPlanFactory.create(reservation.ratePlan);
   124	        BigDecimal refund = tarifPlan.calculateRefund(reservation.amountPaid);
   125	
   126	        reservation.status = ReservationStatus.CANCELLED;
   127	        reservation.refund = refund;
   128	
   129	        return reservationRepo.save(reservation);
   130	    }
   131	
   132	    private void checkRoomAvailability(int roomNumber, LocalDate checkIn, LocalDate checkOut) {
   133	        for (LocalDate date = checkIn; date.isBefore(checkOut); date = date.plusDays(1)) {
   134	            var existing = reservationRepo.findByRoomAndNight(roomNumber, date);
   135	            if (existing.iterator().hasNext()) {
   136	                throw new IllegalArgumentException("Room not available");
   137	            }
   138	        }
   139	    }
   140	}
