    10	    public BigDecimal calculateSubtotal(BigDecimal nightlyRate, int nights, LocalDate checkIn) {
    11	        BigDecimal subtotal = BigDecimal.ZERO;
    12	        for (int i = 0; i < nights; i++) {
    13	            LocalDate night = checkIn.plusDays(i);
    14	            BigDecimal rate = nightlyRate;
    15	            if (DateUtil.isHighSeason(night)) {
