    13	public class OccupancyReportStrategy implements ReportStrategy {
    14	    @Override
    15	    public String generate(ReservationRepository resRepo, RoomRepository roomRepo, Object param) {
    16	        LocalDate date = (LocalDate) param;
    17	        StringBuilder csv = new StringBuilder();
    18	        csv.append("room,type,reservation,check_in,check_out\n");
    19	
    20	        int totalOccupied = 0;
    21	        List<Reservation> occupied = new ArrayList<>();
    22	
    23	        // Collect occupied rooms
    24	        for (Room room : roomRepo.findAll()) {
    25	            for (Reservation res : resRepo.findAll()) {
    26	                if (res.roomNumber == room.number &&
    27	                    res.status == ReservationStatus.CONFIRMED &&
    28	                    !res.checkIn.isAfter(date) &&
    29	                    res.checkOut.isAfter(date)) {
    30	                    occupied.add(res);
    31	                    break;
    32	                }
    33	            }
    34	        }
    35	
    36	        // Sort by room number
    37	        occupied.sort((a, b) -> Integer.compare(a.roomNumber, b.roomNumber));
    38	
    39	        for (Reservation res : occupied) {
    40	            Room room = roomRepo.findByNumber(res.roomNumber).orElseThrow();
    41	            csv.append(res.roomNumber).append(",")
    42	               .append(room.getTypeString()).append(",")
    43	               .append(res.id).append(",")
    44	               .append(DateUtil.formatDateISO(res.checkIn)).append(",")
    45	               .append(DateUtil.formatDateISO(res.checkOut)).append("\n");
    46	            totalOccupied++;
    47	        }
    48	
    49	        int totalRooms = 0;
    50	        for (Room room : roomRepo.findAll()) {
    51	            totalRooms++;
    52	        }
    53	        csv.append("total,").append(totalOccupied).append("/").append(totalRooms).append("\n");
    54	
    55	        return csv.toString();
    56	    }
    57	}
