     1	package com.pousadamarealta.service;
     2	
     3	import com.pousadamarealta.model.Reservation;
     4	import com.pousadamarealta.model.ReservationStatus;
     5	import com.pousadamarealta.repository.ReservationRepository;
     6	import com.pousadamarealta.repository.RoomRepository;
     7	import com.pousadamarealta.util.DateUtil;
     8	import java.math.BigDecimal;
     9	import java.time.YearMonth;
    10	import java.util.ArrayList;
    11	import java.util.Comparator;
    12	import java.util.List;
    13	
    14	public class RevenueReportStrategy implements ReportStrategy {
    15	    @Override
    16	    public String generate(ReservationRepository resRepo, RoomRepository roomRepo, Object param) {
    17	        YearMonth yearMonth = (YearMonth) param;
    18	        StringBuilder csv = new StringBuilder();
    19	        csv.append("reservation,room,check_in,check_out,status,amount\n");
    20	
    21	        List<Reservation> relevant = new ArrayList<>();
    22	
    23	        for (Reservation res : resRepo.findAll()) {
    24	            if (res.checkIn.getYear() == yearMonth.getYear() &&
    25	                res.checkIn.getMonthValue() == yearMonth.getMonthValue() &&
    26	                (res.status == ReservationStatus.CONFIRMED ||
    27	                 res.status == ReservationStatus.CHECKED_IN ||
    28	                 res.status == ReservationStatus.CHECKED_OUT ||
    29	                 res.status == ReservationStatus.CANCELLED)) {
    30	
    31	                // Only count if there's money (confirmed, checked_in, checked_out, or non-refundable cancelled)
    32	                if (!res.amountPaid.equals(BigDecimal.ZERO) || res.status == ReservationStatus.CANCELLED) {
    33	                    relevant.add(res);
    34	                }
    35	            }
    36	        }
    37	
    38	        // Sort by check_in date and then by reservation id
    39	        relevant.sort(Comparator.comparing((Reservation r) -> r.checkIn).thenComparing(r -> r.id));
    40	
    41	        BigDecimal total = BigDecimal.ZERO;
    42	
    43	        for (Reservation res : relevant) {
    44	            BigDecimal amount = calculateAmount(res);
    45	            csv.append(res.id).append(",")
    46	               .append(res.roomNumber).append(",")
    47	               .append(DateUtil.formatDateISO(res.checkIn)).append(",")
    48	               .append(DateUtil.formatDateISO(res.checkOut)).append(",")
    49	               .append(res.status.toString()).append(",")
    50	               .append(amount).append("\n");
    51	            total = total.add(amount);
    52	        }
    53	
    54	        csv.append("total,,,,").append(total).append("\n");
    55	
    56	        return csv.toString();
    57	    }
    58	
    59	    private BigDecimal calculateAmount(Reservation res) {
    60	        BigDecimal amount = res.amountPaid;
    61	        if (res.refund != null) {
    62	            amount = amount.subtract(res.refund);
    63	        }
    64	        return amount;
    65	    }
    66	}
